<?php require_once __DIR__.'/../includes/functions.php';admin_required();$items=[];try{$items=db()->query('SELECT i.*,t.name AS template_name,c.bride_name,c.groom_name FROM invitations i JOIN templates t ON t.id=i.template_id LEFT JOIN couples c ON c.invitation_id=i.id ORDER BY i.created_at DESC')->fetchAll();}catch(Throwable){}$page_title='Invitations';require __DIR__.'/includes/header.php';require __DIR__.'/includes/sidebar.php';?><header class="admin-header"><span class="eyebrow">INVITATIONS</span><h1>Semua undangan</h1></header><section class="table-wrap"><table><thead><tr><th>Slug</th><th>Mempelai</th><th>Template</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><?=e($item['slug'])?></td><td><?=e(trim(($item['bride_name']??'').' & '.($item['groom_name']??''))?:'-')?></td><td><?=e($item['template_name'])?></td><td><?=e($item['status'])?></td><td><a href="/admin/invitation-edit.php?id=<?=e((string)$item['id'])?>">Edit</a></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="5">Belum ada invitation.</td></tr><?php endif;?></tbody></table></section><?php require __DIR__.'/includes/footer.php';?>
